#include <stdio.h>
static void by_value(int v) { v=11; }
static void by_pointer(int *p) { *p=11; }
int main(void) {
    int x=5;
    by_value(x);
    printf("%d\n",x);
    return 0;
}

#include <stdio.h>
static void by_value(int v) { v=11; }
static void by_pointer(int *p) { *p=11; }
int main(void) {
    int x=5;
    by_pointer(&x);
    printf("%d\n",x);
    return 0;
}

#include <stdio.h>
static void by_value(int v) { v=11; }
static void by_pointer(int *p) { *p=11; }
int main(void) {
    int x=5;
    by_pointer(&x);
    by_value(x);
    printf("%d\n",x);
    return 0;
}
